// Import the PrismaClient class generated by Prisma.
// The generated client contains methods for each model
// defined in schema.prisma (e.g., User, Job, Proposal).
import { PrismaClient } from "@prisma/client";

// Instantiate PrismaClient to establish a connection interface
// between the application and the PostgreSQL database.
//
// By exporting this instance, other files can import and reuse
// the same client rather than creating multiple database connections.
export const prisma = new PrismaClient();